<script setup lang="ts">definePageMeta({layout:'app'});import type {Session} from '~/types';const rows=ref<Session[]>([]),teachers=ref<any[]>([]),modal=ref(false),edit=ref<Session|null>(null),from=ref(new Date().toISOString().slice(0,10));const {error,run}=useApiError();async function load(){const end=new Date(from.value);end.setDate(end.getDate()+60);rows.value=(await api<any>(`/sessions?from=${from.value}&to=${end.toISOString().slice(0,10)}`)).data||[]}async function cancel(s:Session){if(!confirm(`確定取消「${s.title}」？`))return;await run(()=>api(`/sessions/${s.id}`,{method:'PUT',body:{version:s.version,status:'cancelled',reason:'管理者取消場次'}}));await load()}onMounted(async()=>{await load();teachers.value=(await api<any>('/teachers')).data||[]})</script>
<template><div class="workhead"><div><p class="eyebrow">ADMIN SCHEDULE</p><h1>排程管理</h1></div><div class="toolbar"><input v-model="from" type="date" @change="load"><button class="button" @click="edit=null;modal=true">建立場次</button></div></div><div class="notice">支援建立重複場次、教師指派與版本衝突保護；衝突可由後端回傳後重新調整。</div><div class="tablewrap" style="margin-top:16px"><table class="table"><thead><tr><th>日期時間</th><th>服務</th><th>地點</th><th>同工</th><th>狀態</th><th></th></tr></thead><tbody><tr v-for="s in rows" :key="s.id"><td>{{s.service_date}} {{s.start_time}}</td><td>{{s.title}}<br><small>{{s.prison}}</small></td><td>{{s.location}}</td><td>{{s.assignments.map(a=>a.teacher?.name).join('、')}}</td><td><span :class="['status',s.status]">{{s.status}}</span></td><td><button class="button ghost" @click="edit=s;modal=true">編輯</button> <button class="button danger" @click="cancel(s)">取消</button></td></tr></tbody></table></div><p v-if="error" class="error">{{error}}</p><SessionEditor v-if="modal" :session="edit" :teachers="teachers" @close="modal=false" @saved="load"/></template>
